    private void requireAccount(long id){if(!repository.accountExists(id))throw new DepositAccountNotFoundException("حساب سپرده یافت نشد: "+id);}
    private void requireParty(long aid,long pid,String field){if(!repository.activeAccountParty(aid,pid))throw new IllegalArgumentException(field+" باید Party فعال حساب باشد.");}
    private void validateTarget(long accountId,String channel,String target){if(("EMAIL".equals(channel)||"SMS".equals(channel))&&!repository.activeContact(accountId,channel,target))throw new IllegalArgumentException("مقصد "+channel+" باید Contact فعال حساب باشد.");}
    private boolean replayOrClaim(String key,long accountId,String operation,String payloadHash,String actor,String correlation){String k=required(key,"X-Idempotency-Key");var row=repository.idempotency(k);if(row.isPresent()){IdemRow x=row.get();if(!operation.equals(x.operation())||!payloadHash.equals(x.payloadHash())||!Objects.equals(accountId,x.accountId()))throw new IllegalArgumentException("Idempotency-Key با payload قبلی سازگار نیست.");if("COMPLETED".equals(x.status()))return true;throw new IllegalStateException("درخواست با Idempotency-Key در حال پردازش است.");}repository.claimIdempotency(repository.next("SEQ_DEPOSIT_OPERATION_IDEMPOTENCY"),k,accountId,operation,payloadHash,actor,correlation);return false;}
    private static String required(String v,String field){if(v==null||v.isBlank())throw new IllegalArgumentException(field+" الزامی است.");return v.trim();}
    private static String trim(String v){return v==null||v.isBlank()?null:v.trim();}
    private static String upper(String v){return v==null?null:v.trim().toUpperCase(Locale.ROOT);}
    private static String hash(String s){try{byte[] d=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));return java.util.HexFormat.of().formatHex(d);}catch(Exception e){throw new IllegalStateException(e);}}
